/// The mark drawn for a built-in vendor, `None` for custom endpoints.
pub fn logo(vendor: &str) -> Option<&'static Icon> {
    match vendor {
        "anthropic" => Some(&ANTHROPIC),
        "openai" => Some(&OPENAI),
        "google" => Some(&GOOGLE),
        "openrouter" => Some(&OPENROUTER),
        "deepseek" => Some(&DEEPSEEK),
        "moonshot" => Some(&MOONSHOT),
        "xai" => Some(&XAI),
        "mistral" => Some(&MISTRAL),
        "groq" => Some(&GROQ),
        "together" => Some(&TOGETHER),
        "fireworks" => Some(&FIREWORKS),
        "siliconflow" => Some(&SILICONFLOW),
        "zhipu" => Some(&ZHIPU),
        "zai" => Some(&ZAI),
        "minimax" => Some(&MINIMAX),
        "qwen" => Some(&QWEN),
        "stepfun" => Some(&STEPFUN),
        "nvidia" => Some(&NVIDIA),
        "vercel" => Some(&VERCEL),
        "modelscope" => Some(&MODELSCOPE),
        "ollama" | "ollama-cloud" => Some(&OLLAMA),
        "lmstudio" => Some(&LMSTUDIO),
        "omlx" => Some(&OMLX),
        "magpie" => Some(&MAGPIE),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    #[test]
    fn every_catalog_vendor_has_a_mark() {
        for vendor in llm::vendors::catalog::catalog() {
            assert!(
                super::logo(vendor.id).is_some(),
                "{} has no mark",
                vendor.id
            );
        }
        assert!(super::logo("custom-gateway").is_none());
    }
}
